-- Vollständiger Neuaufbau: einfach und von selbst idempotent
DROP TABLE IF EXISTS clean.fahrt;
CREATE TABLE clean.fahrt AS
SELECT fahrt_id, rad_id, kunde_id, start_station, ziel_station,
       start_zeit, dauer_min, preis_eur::numeric(6,2) AS preis_eur
FROM staging.fahrt;

-- Einen Monat nachladen: erst löschen, dann einfügen, in EINER Transaktion
BEGIN;
DELETE FROM clean.fahrt
 WHERE start_zeit >= DATE '2026-08-01' AND start_zeit < DATE '2026-09-01';
INSERT INTO clean.fahrt (fahrt_id, rad_id, kunde_id, start_station, ziel_station,
                         start_zeit, dauer_min, preis_eur)
SELECT fahrt_id, rad_id, kunde_id, start_station, ziel_station,
       start_zeit, dauer_min, preis_eur
FROM staging.fahrt
 WHERE start_zeit >= DATE '2026-08-01' AND start_zeit < DATE '2026-09-01';
COMMIT;

